-- ============================================================
-- SEED EXT 6: Módulo 11 — Relative Clauses (ex 205-300)
-- Tópicos: defining/non-defining avançadas, quantified relatives,
-- prepositional relatives, relatives empilhadas, TOEFL integrado
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'relative-clauses';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo relative-clauses não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 71: Defining relative clauses avançadas com who/which/that
  (cid,71,205,'gap_fill','_____ (the) _____ institutions _____ (that/most/effective/be) are those _____ (maintain) _____ (a) _____ culture of _____ (accountability) in _____ which _____ (performance) _____ (openly/assess/passive) and _____ (failure) _____ (meet/passive) with _____ (genuine/consequence) rather than _____ (manage) _____ (communication/through).','The / institutions / that / are most effective / that / maintain / a / culture / accountability / which / performance / is openly assessed / failure / is met / genuine / consequences / rather / managed / through / communication',NULL,'Defining RC "that are most effective/that maintain" for institutional effectiveness.','hard'),
  (cid,71,206,'gap_fill','Research _____ (that) _____ (merely/confirm) _____ (what) _____ (already/know/passive) _____ (unlikely/be) to _____ (generate) _____ (the) _____ kind of _____ (insight) _____ (capable/be) of _____ (transform) _____ practice — it _____ (the/questions/be) _____ (challenge) _____ (assumption/accepted) _____ (that/most/valuable/prove).','Research / that / merely confirms / what / is already known / is unlikely / to generate / the / kind / of / insights / that are capable of / transforming / it is the questions / that challenge / accepted / assumptions / that prove most valuable',NULL,'Stacked defining RCs: "that merely confirms" + "that are capable" + "that challenge...that prove."','hard'),
  (cid,71,207,'gap_fill','_____ (the) _____ approaches _____ (that) _____ (gain) _____ (the/most/traction) in _____ (the) _____ policy _____ arena _____ (not/always/be) those _____ (best/support/passive) by _____ (the) _____ evidence — _____ (factors) _____ (align/passive) with _____ political _____ (incentive) _____ (often/have) _____ (as/much/weight) as _____ (the/quality) of _____ (the) _____ underlying _____ research.','The / approaches / that / gain / the most traction / in / the / policy / arena / are not always those / best supported / the / evidence / factors / that / align / political / incentives / often have / as much weight / as / the quality / the / underlying / research',NULL,'Defining RC "that gain/best supported/that align" for policy-evidence gap analysis.','hard'),
  (cid,71,208,'gap_fill','_____ (the) _____ conditions _____ (that) _____ (most/effective/make) _____ an _____ intervention _____ (not/always/be) the _____ same as those _____ (most/feasible/make) it _____ to _____ (implement) — _____ (a) _____ tension _____ (require) _____ (those) _____ (design) _____ programs to _____ (balance) _____ fidelity against _____ adaptability.','The / conditions / that / make / most effective / an / intervention / are not always / those / that make / most feasible / implement / a / tension / that requires / those / designing / programs / balance / fidelity / adaptability',NULL,'Parallel defining RCs "that make most effective/feasible" for program design tension.','hard'),
  (cid,71,209,'gap_fill','Policies _____ (target) _____ (the/symptoms) of _____ (a) _____ problem rather than _____ (the/causes) _____ (that/drive) it _____ (unlikely/be) to _____ (produce) _____ lasting _____ change — (they) _____ (may/provide) _____ temporary _____ relief, but _____ (the/dynamics) _____ (generate) _____ (the) _____ problem in _____ (the/first/place) _____ (persist).','Policies / that target / the symptoms / a / problem / the causes / that drive / are unlikely / produce / lasting / change / they / may provide / temporary / relief / the dynamics / that generate / the / problem / in the first place / persist',NULL,'Defining RCs "that target/that drive/that generate" for structural vs symptomatic intervention.','hard'),
  (cid,71,210,'gap_fill','_____ (the) _____ leaders _____ (that) _____ (create) _____ lasting _____ institutional _____ change _____ typically _____ those _____ (invest) _____ in _____ (the) _____ relationships and _____ capabilities _____ (sustain) _____ (the) _____ reform _____ beyond _____ their _____ own _____ tenure — not those _____ (rely) on _____ (personal) _____ authority.','The / leaders / that / create / lasting / institutional / change / are typically those / who invest / in / the / relationships / capabilities / that sustain / the / reform / beyond / their / own / tenure / not those / who rely on / personal / authority',NULL,'Defining RCs "that create/who invest/that sustain/who rely" for institutional change leadership.','hard'),
  (cid,71,211,'multiple_choice','Which defining relative clause MOST PRECISELY identifies a referent in formal academic writing?','The framework that has generated the most productive research program is the one that makes the most falsifiable predictions.','["The framework which generated the most productive research is one that makes falsifiable predictions.","The framework that has generated the most productive research program is the one that makes the most falsifiable predictions.","The framework, which generated productive research, is one making falsifiable predictions.","A framework generating productive research makes falsifiable predictions."]','Double defining RC "that has generated/that makes" precisely identifies both the framework and its key characteristic.','medium'),
  (cid,71,212,'gap_fill','Any _____ (theory) _____ (that) _____ (claim) to _____ (explain) _____ all _____ (the) _____ relevant _____ (phenomenon) without _____ (exception) _____ (suspect/be) — _____ genuine _____ understanding _____ (produce) by _____ (the) _____ theories _____ (take) _____ (the/anomalies/seriously) they _____ encounter rather than _____ (explain them away).','Any / theory / that / claims / explain / all / the / relevant / phenomena / without / exception / is suspect / genuine / understanding / is produced / by / the / theories / that take / the anomalies seriously / they / encounter / rather / explaining them away',NULL,'Defining RC "that claims/that take seriously" for epistemological quality of theories.','hard'),

  -- BLOCK 72: Relative clauses com whose e whom
  (cid,72,213,'gap_fill','_____ (the) _____ researchers _____ (whose) _____ work _____ (shape) _____ (the) _____ direction of _____ (the) _____ field _____ over _____ (the) _____ past _____ decade _____ (share) _____ (a) _____ commitment to _____ methodological _____ rigor _____ (distinguish) them from _____ (those/whose) _____ (contribution) _____ (fail) to _____ (survive) _____ (the) _____ scrutiny of _____ replication.','The / researchers / whose / work / shaped / the / direction / the / field / over / the / past / decade / share / a / commitment / methodological / rigor / that distinguishes / those / whose / contributions / failed / survive / the / scrutiny / replication',NULL,'"Whose" RC "whose work shaped" + "whose contributions failed" for parallel researcher contrast.','hard'),
  (cid,72,214,'gap_fill','This _____ opportunity _____ (present) _____ itself _____ rarely to _____ (those) _____ for _____ whom _____ (the) _____ timing _____ (align) _____ with _____ their _____ other _____ commitments — those _____ (to/whom) _____ it _____ (offer) now _____ (be) in _____ (a) _____ position to _____ (shape) _____ (the) _____ outcome.','This / opportunity / presents / itself / rarely / those / for / whom / the / timing / aligns / with / their / other / commitments / those / to whom / it / is offered / now / are / a / position / shape / the / outcome',NULL,'"For whom" + "to whom" prepositional relatives in formal opportunity context.','hard'),
  (cid,72,215,'gap_fill','_____ communities _____ (whose) _____ institutions _____ (erode/passive) over _____ time _____ (struggle) to _____ (generate) _____ (the) _____ collective _____ responses _____ (require/passive) to _____ (address) _____ common _____ challenges — _____ (the) _____ social _____ capital _____ on _____ which _____ (their) _____ (adaptive) _____ capacity _____ (depend) _____ (no longer/exist).','Communities / whose / institutions / have been eroded / over / time / struggle / generate / the / collective / responses / required / address / common / challenges / the / social / capital / on which / their / adaptive / capacity / depends / no longer exists',NULL,'"Whose institutions" + "on which...depends" for community institution erosion.','hard'),
  (cid,72,216,'gap_fill','Those _____ (to) _____ whom _____ (the) _____ information _____ (entrust/passive) _____ (bear) _____ (a) _____ special _____ responsibility to _____ (handle) it _____ with _____ (care) — _____ (the) _____ individuals _____ (whose) _____ (judgment) _____ others _____ (rely) on _____ to _____ (make) _____ these _____ distinctions _____ (cannot) _____ (afford) to _____ (be) _____ (wrong).','Those / to / whom / the / information / is entrusted / bear / a / special / responsibility / handle / with / care / the / individuals / whose / judgment / others / rely on / make / these / distinctions / cannot / afford / be / wrong',NULL,'"To whom...entrusted" + "whose judgment" for epistemic responsibility in information handling.','hard'),
  (cid,72,217,'gap_fill','_____ (the) _____ analysts _____ (whose) _____ _____ (forecasting) _____ (prove) most _____ (accurate) _____ (over/time) _____ (share) _____ (a) _____ common _____ characteristic: they _____ (acknowledge) _____ (their) _____ own _____ uncertainty rather than _____ (project) _____ (false) _____ confidence _____ to _____ those _____ (for/whom/analyze/passive) they.','The / analysts / whose / forecasting / has proved / most / accurate / over time / share / a / common / characteristic / acknowledge / their / own / uncertainty / rather / projecting / false / confidence / to / those / for whom / they analyze',NULL,'"Whose forecasting" + "for whom they analyze" for epistemic humility in forecasting.','hard'),
  (cid,72,218,'multiple_choice','Which sentence MOST correctly uses "whose" in a formal academic context?','The committee, whose recommendations carry significant weight, has yet to release its final report.','["The committee, who''s recommendations carry significant weight, has yet to release its final report.","The committee, which recommendations carry significant weight, has yet to release its final report.","The committee, whose recommendations carry significant weight, has yet to release its final report.","The committee, that recommendations carry significant weight, has yet to release its final report."]','"Whose recommendations" = correct possessive relative for institutions/things. "Who''s" = "who is" (wrong). "Which recommendations" is non-standard.','easy'),
  (cid,72,219,'gap_fill','_____ scholars _____ (with/whose) _____ work _____ (disagree/we) _____ (deserve) _____ careful _____ engagement rather than _____ dismissal — _____ (the) _____ positions _____ (against/which) _____ we _____ (argue) _____ (should) _____ (represent/passive) accurately if _____ (the) _____ counter-argument _____ to _____ (have) _____ force.','The / scholars / with whose work / we disagree / deserve / careful / engagement / rather / dismissal / the / positions / against which / we / argue / should / be represented / accurately / if / the / counter-argument / to / have / force',NULL,'"With whose work" + "against which" for academic intellectual engagement ethic.','hard'),
  (cid,72,220,'gap_fill','_____ leaders _____ (in/whom) _____ citizens _____ (place) _____ (their) _____ trust _____ (bear) _____ (an) _____ obligation to _____ (use) that _____ trust in _____ (the/service) of _____ (the) _____ public _____ (interest) rather than _____ in _____ (the) _____ service of _____ their _____ own _____ advancement.','The / leaders / in whom / citizens / place / their / trust / bear / an / obligation / use / that / trust / in the service / the / public / interest / rather / in / the / service / their / own / advancement',NULL,'"In whom citizens place trust" for prepositional relative in democratic accountability context.','hard'),

  -- BLOCK 73: Relative clauses com where, when, why
  (cid,73,221,'gap_fill','_____ (the) _____ contexts _____ (where) _____ _____ (the) _____ intervention _____ (prove) most _____ (effective) _____ (be) those _____ in _____ which _____ (both) _____ (implementation) _____ (fidelity) and _____ community _____ (engagement) _____ (high) — _____ (the/factors/these/two) _____ (together/appear) to _____ (function) as _____ (necessary/complements).','The / contexts / where / the / intervention / proved / most / effective / were / those / in / which / both / implementation / fidelity / and / community / engagement / were high / these two factors / together appear / function / necessary / complements',NULL,'"Where the intervention proved" + "in which both...were high" for context-effectiveness analysis.','hard'),
  (cid,73,222,'gap_fill','There _____ (are) _____ (moment) in _____ (institutional) _____ life _____ (when) _____ (the) _____ accumulated _____ (tension) _____ (reach) _____ (a) _____ critical _____ point and _____ incremental _____ change _____ (no longer/sufficient/be) — _____ (at/these/moment), _____ (the) _____ capacity for _____ discontinuous _____ (reform) _____ (what/distinguish) _____ (the) _____ adaptive from _____ the _____ brittle.','are / moments / in / institutional / life / when / the / accumulated / tensions / reach / a / critical / point / and / incremental / change / is no longer sufficient / at these moments / the / capacity / discontinuous / reform / is what distinguishes / the / adaptive / brittle',NULL,'"When the accumulated tensions reach" + relative clause for institutional tipping points.','hard'),
  (cid,73,223,'gap_fill','_____ (the) _____ reason _____ (why) _____ (some) _____ (reform) _____ (succeed) _____ where _____ others _____ (fail) _____ (complex/be) and _____ contested — _____ (what) _____ (clear/seem) is that _____ (the) _____ explanations _____ (most/plausible/prove) _____ (point) to _____ (the) _____ quality of _____ implementation rather than _____ of _____ design.','The / reason / why / some / reforms / succeed / where / others / fail / is complex / contested / what / seems clear / is / the / explanations / most plausible / point / the / quality / implementation / rather / design',NULL,'"Why some reforms succeed/others fail" + "where others fail" for reform success analysis.','hard'),
  (cid,73,224,'gap_fill','In _____ (the) _____ conditions _____ (where) _____ (the) _____ state _____ (cannot) _____ (provide) _____ adequate _____ (public) _____ services, _____ civil _____ society _____ (step in) to _____ (fill) _____ (the) _____ gap — creating _____ hybrid _____ arrangements _____ where _____ (the) _____ (boundaries) between _____ public and _____ private _____ (blur).','In / the / conditions / where / the / state / cannot / provide / adequate / public / services / civil / society / steps in / fill / the / gap / creating / hybrid / arrangements / where / the / boundaries / between / public / private / blur',NULL,'"Where the state cannot provide" + "where the boundaries blur" for state-society gap.','hard'),
  (cid,73,225,'gap_fill','_____ (the) _____ moment _____ (when) _____ (the) _____ case _____ for _____ action _____ (become) _____ incontrovertible _____ often _____ (arrive) too _____ late — _____ (by/the/time) _____ (the) _____ evidence _____ (accumulate) to _____ (the) _____ point _____ (where) _____ doubters _____ (convince/passive), _____ (the) _____ window for _____ effective _____ action _____ (often/narrow).','The / moment / when / the / case / for / action / becomes / incontrovertible / often / arrives / too / late / by the time / the / evidence / accumulates / to / the / point / where / doubters / are convinced / the / window / effective / action / has often narrowed',NULL,'"When the case becomes" + "where doubters are convinced" for policy timing problem.','hard'),
  (cid,73,226,'gap_fill','There _____ (are) _____ (circumstances) _____ (under/which) _____ (the) _____ normal _____ rules _____ (suspend/passive) and _____ emergency _____ (power) _____ (invoke/passive) — and _____ (precisely) _____ _____ (circumstances/these) _____ (make) _____ clear _____ why _____ (the) _____ institutional _____ (safeguard) _____ (prevent/passive) abuse _____ (most/matter) most.','are / circumstances / under which / the / normal / rules / are suspended / emergency / powers / invoked / and / precisely / these circumstances / make / clear / why / the / institutional / safeguards / designed to prevent / abuse / matter most',NULL,'"Under which the rules are suspended" + "why the safeguards matter" for emergency powers argument.','hard'),
  (cid,73,227,'multiple_choice','Which sentence MOST effectively uses a relative clause with "where" in a formal academic context?','The studies produced the most reliable results in contexts where the implementation conditions most closely matched the design specifications.','["The studies produced most reliable results where conditions matched design.","The studies produced the most reliable results in contexts where the implementation conditions most closely matched the design specifications.","The studies, where producing most reliable results, matched design specifications.","The studies produced reliable results in contexts which conditions matched specifications."]','"Where the implementation conditions matched" = precise RC identifying the effective context.','easy'),
  (cid,73,228,'gap_fill','This _____ (be) _____ precisely _____ (the) _____ (kind/of) _____ situation _____ where _____ (the) _____ absence of _____ (a) _____ clear _____ decision-making _____ (framework) _____ (create) _____ dangerous _____ ambiguity — (the) _____ (reason) _____ why _____ (the) _____ protocols _____ (establish) in _____ advance _____ _____ (rather/than) ad hoc _____ arrangement _____ _____ (improvise/passive) under _____ (pressure) _____ (need/passive) to.','This / is / precisely / the / kind of / situation / where / the / absence / a / clear / decision-making / framework / creates / dangerous / ambiguity / the / reason / why / the / protocols / established / in advance / rather / than / ad hoc / arrangements / improvised / under / pressure / are needed',NULL,'"Where...creates" + "why protocols...are needed" for advance planning rationale.','hard'),

  -- BLOCK 74: Quantified relatives (most of which, many of whom)
  (cid,74,229,'gap_fill','_____ (the) _____ committee _____ (receive) _____ more _____ than _____ two _____ hundred _____ (submission), _____ (most/of/which) _____ (address) _____ (the) _____ procedural _____ (concern) _____ (raise/passive) at _____ (the) _____ consultation _____ meeting, _____ (though) _____ (several/of/which) _____ (focus) on _____ broader _____ structural _____ issues.','The / committee / received / more / than / two / hundred / submissions / most of which / addressed / the / procedural / concerns / raised / the / consultation / meeting / though / several of which / focused / broader / structural / issues',NULL,'"Most of which" + "several of which" for quantified partitive relative clauses.','medium'),
  (cid,74,230,'gap_fill','_____ (the) _____ program _____ (recruit) _____ (a) _____ cohort of _____ fifty _____ (young) _____ leaders, _____ (many/of/whom) _____ (go on) to _____ (hold) _____ (senior) _____ positions in _____ government and _____ (the) _____ private _____ sector — (a) _____ alumni _____ (network) _____ (become) one of _____ (the/program''s) _____ most _____ tangible _____ legacies.','The / program / recruited / a / cohort / fifty / young / leaders / many of whom / went on / hold / senior / positions / government / the / private / sector / an / alumni / network / that became / the program''s / most / tangible / legacies',NULL,'"Many of whom went on to hold" for cohort relative with "that became" appositive.','hard'),
  (cid,74,231,'gap_fill','_____ (the) _____ country _____ (implement) _____ (a) _____ comprehensive _____ set of _____ (reform), _____ (some/of/which) _____ (prove) _____ (transformative) and _____ (others/of/which) _____ (fall short) of _____ (their) _____ potential due to _____ (implementation) _____ (weakness).','The / country / implemented / a / comprehensive / set / reforms / some of which / proved / transformative / others of which / fell short / their / potential / due / implementation / weaknesses',NULL,'"Some of which" + "others of which" for contrasted quantified relative clauses.','medium'),
  (cid,74,232,'gap_fill','_____ (the) _____ participants _____ (interview) _____ for _____ (this) _____ study, _____ (all/of/whom) _____ (have) _____ (direct) _____ experience with _____ (the) _____ program, _____ (provide) _____ nuanced _____ perspectives that _____ (reflect) _____ both _____ (the) _____ program''s _____ strengths and _____ (its) _____ limitations.','The / participants / interviewed / for / this / study / all of whom / had / direct / experience / the / program / provided / nuanced / perspectives / reflected / both / the / program''s / strengths / its / limitations',NULL,'"All of whom had direct experience" for universal quantified relative in research context.','medium'),
  (cid,74,233,'gap_fill','_____ government _____ (introduce) _____ (a) _____ series of _____ (initiative), _____ (each/of/which) _____ (address) _____ (a) _____ different _____ (aspect) of _____ (the) _____ problem, but _____ (none/of/which) _____ (designed/passive) to _____ (function) as _____ (a) _____ coherent _____ and _____ integrated _____ response.','The / government / introduced / a / series / initiatives / each of which / addressed / a / different / aspect / the / problem / none of which / was designed / to / function / as / a / coherent / integrated / response',NULL,'"Each of which addressed" + "none of which was designed" for piecemeal policy critique.','hard'),
  (cid,74,234,'gap_fill','_____ (the) _____ study _____ (involve) _____ (a) _____ sample of _____ three _____ hundred _____ (household), _____ (two-thirds/of/which) _____ (locate/passive) in _____ (urban) _____ areas and _____ (one-third/of/which) _____ (rural/be), _____ (allow) _____ comparison across _____ (the) _____ urban-rural _____ divide.','The / study / involved / a / sample / three / hundred / households / two-thirds of which / were located / in / urban / areas / one-third of which / were rural / allowing / comparison / across / the / urban-rural / divide',NULL,'"Two-thirds of which" + "one-third of which" for fractional quantified relative in research.','medium'),
  (cid,74,235,'multiple_choice','Which quantified relative clause construction is MOST FORMAL and precise?','The report examined twelve case studies, the findings of which were then synthesized to identify common patterns.','["The report examined twelve case studies, and their findings were synthesized.","The report examined twelve case studies, most of which had findings.","The report examined twelve case studies, the findings of which were then synthesized to identify common patterns.","The report examined twelve case studies, which all had findings synthesized."]','"The findings of which were synthesized" = most formal prepositional quantified relative.','medium'),
  (cid,74,236,'gap_fill','_____ (the) _____ agencies _____ (responsible) for _____ (implementation), _____ (several/of/which) _____ (lack) _____ adequate _____ (capacity) and _____ (few/of/which) _____ (receive) _____ (the) _____ resources _____ (need/passive) to _____ (perform) _____ (their) _____ functions _____ effectively, _____ (face) _____ (an) _____ almost _____ impossible _____ task.','The / agencies / responsible / implementation / several of which / lacked / adequate / capacity / few of which / received / the / resources / needed / perform / their / functions / effectively / faced / an / almost / impossible / task',NULL,'"Several of which lacked" + "few of which received" for implementing agency capacity critique.','hard'),

  -- BLOCK 75: Relative clauses com preposições
  (cid,75,237,'gap_fill','_____ (the) _____ framework _____ (within/which) _____ (the) _____ analysis _____ (conduct/passive) _____ (shape) _____ (the) _____ kind of _____ (question) it _____ (can) _____ (address) — _____ (the) _____ assumptions _____ (on/which) it _____ (rest) _____ (pre-determine/passive) _____ (the) _____ range of _____ (answer) it _____ (capable) of _____ generating.','The / framework / within which / the / analysis / is conducted / shapes / the / kind / questions / can / address / the / assumptions / on which / it / rests / predetermine / the / range / answers / is capable / generating',NULL,'"Within which the analysis is conducted" + "on which it rests" for epistemological framing.','hard'),
  (cid,75,238,'gap_fill','_____ (the) _____ (mechanism) _____ (through/which) _____ change _____ (occur) _____ (matter) as _____ much _____ as _____ the _____ (fact) that _____ change _____ (occur) — _____ (the/way) in _____ (which) _____ something _____ (achieve/passive) _____ (affect) _____ whether _____ (it) _____ (sustain/passive) _____ over _____ time.','The / mechanisms / through which / change / occurs / matter / as / much / as / the / fact / that / change / occurs / the way / in which / something / is achieved / affects / whether / it / will be sustained / over / time',NULL,'"Through which change occurs" + "in which something is achieved" for process-outcome analysis.','hard'),
  (cid,75,239,'gap_fill','_____ (the) _____ (conditions) _____ (under/which) _____ (the) _____ agreement _____ (negotiate/passive) _____ (bear) heavily on _____ (its) _____ content — _____ (the) _____ asymmetries of _____ (power) _____ (between/which) _____ (the/parties) _____ (negotiate) _____ (reflect/passive) in _____ (the) _____ terms _____ (eventually/reach/passive).','The / conditions / under which / the / agreement / was negotiated / bore / heavily / its / content / the / asymmetries / power / between which / the parties / negotiated / were reflected / the / terms / eventually reached',NULL,'"Under which the agreement was negotiated" + "between which parties negotiated" for power asymmetry in negotiations.','hard'),
  (cid,75,240,'gap_fill','_____ (the) _____ evidence _____ (on/which) _____ (the) _____ policy _____ (base/passive) _____ (contest/passive) — _____ (the) _____ methodologies _____ (by/which) it _____ (generate/passive) _____ (subject/passive) to _____ criticism from _____ (several) _____ independent _____ (reviewer).','The / evidence / on which / the / policy / is based / is contested / the / methodologies / by which / it / was generated / have been subjected / to / criticism / several / independent / reviewers',NULL,'"On which the policy is based" + "by which it was generated" for evidence quality scrutiny.','hard'),
  (cid,75,241,'gap_fill','The _____ (arena) _____ (in/which) _____ (these) _____ (contest) _____ (play out) _____ (determine) _____ not just _____ (the) _____ immediate _____ (outcome) but _____ (the) _____ rules _____ _____ (by/which) _____ future _____ (contest) _____ (govern/passive) — _____ (a) _____ (reason) for _____ (the) _____ intensity of _____ competition over _____ (institutional) _____ design.','The / arena / in which / these / contests / play out / determines / not / the / immediate / outcomes / the / rules / by which / future / contests / are governed / a / reason / for / the / intensity / competition / institutional / design',NULL,'"In which contests play out" + "by which contests are governed" for meta-institutional stakes.','hard'),
  (cid,75,242,'multiple_choice','Which prepositional relative clause construction is MOST appropriate in formal academic writing?','The criteria by which the proposals were evaluated were established in advance.','["The criteria that the proposals were evaluated by were established in advance.","The criteria which they evaluated the proposals by were established in advance.","The criteria by which the proposals were evaluated were established in advance.","The criteria the proposals were evaluated by were established in advance."]','"By which the proposals were evaluated" = correct formal prepositional relative. Stranded preposition is informal.','easy'),
  (cid,75,243,'gap_fill','_____ (the/purpose) _____ (for/which) _____ (the) _____ data _____ (collect/passive) _____ (should) _____ (determine) _____ (the) _____ methods _____ (by/which) _____ they _____ (analyze/passive) — _____ (the) _____ (confusion) of _____ (purpose) and _____ method _____ (be) _____ (a) _____ common _____ source of _____ analytic _____ (error).','The / purpose / for which / the / data / were collected / should / determine / the / methods / by which / they / are analyzed / the / confusion / of / purpose / method / is / a / common / source / analytic / error',NULL,'"For which the data were collected" + "by which they are analyzed" for research design alignment.','hard'),
  (cid,75,244,'gap_fill','The _____ (degree) to _____ which _____ (the) _____ institution _____ (meet) _____ (its) _____ stated _____ (commitment) _____ (depend) on _____ (the) _____ extent to _____ which _____ (those/responsible) for _____ (its) _____ governance _____ (take) those _____ (commitment) _____ seriously _____ in _____ their _____ day-to-day _____ decisions.','The / degree / to which / the / institution / meets / its / stated / commitments / depends / the / extent / to which / those responsible / its / governance / take / those / commitments / seriously / their / day-to-day / decisions',NULL,'"To which the institution meets" + "to which those responsible take" for institutional commitment analysis.','hard'),

  -- BLOCK 76: TOEFL Reading com relative clauses
  (cid,76,245,'multiple_choice','[TOEFL Reading] "The scientists who conducted the study found results that challenged the prevailing theory." The relative clause "who conducted the study" is:','A defining relative clause that identifies which scientists are referred to.','["A non-defining clause adding extra information about all scientists","A defining relative clause that identifies which scientists are referred to.","A clause expressing time","A relative clause modifying "results""]','Defining RC "who conducted the study" = identifies WHICH scientists (not all scientists, just these ones).','easy'),
  (cid,76,246,'gap_fill','[TOEFL Reading] "The approach _____ (the/researchers) _____ (develop) _____ (build/passive) on _____ (the) _____ earlier _____ work of _____ (scholars) _____ (whose) _____ (theoretical) _____ contributions _____ (not/yet/adequately) _____ (recognise/passive)." Best forms?','the researchers / developed / builds / on / the / earlier / work / scholars / whose / theoretical / contributions / had not yet been adequately / recognised',NULL,'Defining RC "the researchers developed" + "whose contributions had not been recognised."','medium'),
  (cid,76,247,'gap_fill','[TOEFL Reading] "The conditions _____ (under/which) _____ (the) _____ phenomenon _____ (occur) _____ (poorly/understand/passive) — _____ (there) _____ are _____ multiple _____ (competing) _____ hypotheses, _____ (none/of/which) _____ (adequately/test/passive)." Best forms?','under which / the / phenomenon / occurs / are poorly understood / there / competing / hypotheses / none of which / have been adequately tested',NULL,'"Under which occurs" + "none of which have been tested" for reading analysis.','medium'),
  (cid,76,248,'gap_fill','[TOEFL Reading] "The institution, _____ (mandate) _____ (define/passive) _____ broadly, _____ (face) _____ (pressure) from _____ (member/states), _____ (many/of/whom) _____ (interpret) _____ that _____ (mandate) _____ (very/differently)." Best forms?','whose / mandate / is broadly defined / faces / pressure / member states / many of whom / interpret / that / mandate / very differently',NULL,'"Whose mandate is defined" + "many of whom interpret" for institution mandate analysis.','medium'),
  (cid,76,249,'gap_fill','[TOEFL Reading] "The model _____ (gain) _____ (the/most/attention) in _____ (the) _____ literature _____ (one/that) _____ (predict) _____ outcomes _____ more _____ accurately than _____ (the) _____ alternatives _____ (against/which) _____ (it) _____ (test/passive)." Best forms?','that gained / the most attention / in / the / literature / is the one that / predicts / outcomes / more / accurately / than / the / alternatives / against which / it / was tested',NULL,'"That gained most attention" + "one that predicts" + "against which it was tested."','hard'),
  (cid,76,250,'multiple_choice','[TOEFL Reading] "The policy, which was adopted without adequate consultation, has faced significant implementation challenges." What does the relative clause tell us?','Additional information about the policy, not needed to identify which policy.','["Which policy we are talking about","Additional information about the policy, not needed to identify which policy.","The reason the policy was adopted","A condition for implementation"]','Non-defining RC (commas) "which was adopted without consultation" = extra information about an already-identified policy.','easy'),
  (cid,76,251,'gap_fill','[TOEFL Reading] "The populations _____ (most/affect/passive) by _____ (the) _____ change _____ (those/be) _____ for _____ whom _____ (the) _____ adjustment _____ costs _____ (too/high/be) to _____ absorb _____ without _____ support — _____ (the/very/those) _____ (least/likely/be) to _____ receive it." Best forms?','most affected / the / change / are those / for whom / the / adjustment / costs / are too high / to / absorb / without / support / the very ones / least likely / receive',NULL,'"Most affected by" + "for whom costs are too high" + "least likely to receive" for distributional analysis.','hard'),
  (cid,76,252,'gap_fill','[TOEFL Reading] "The reason _____ (why) _____ (the) _____ reform _____ (succeed) _____ (where) _____ (similar) _____ (effort) _____ (fail) _____ (lie) in _____ (the) _____ quality of _____ (the) _____ political _____ coalition _____ _____ (which/behind) _____ (it) _____ (build)." Best forms?','why / the / reform / succeeded / where / similar / efforts / had failed / lies / in / the / quality / the / political / coalition / behind which / it / was built',NULL,'"Why the reform succeeded/where efforts had failed" + "behind which it was built" for reform success analysis.','hard'),

  -- BLOCK 77: TOEFL Speaking com relative clauses
  (cid,77,253,'production','[TOEFL Speaking — 45s] A reading describes an organization that has implemented reforms. Summarize using relative clauses.','',NULL,'The reading describes an organization that has undergone significant reforms over the past decade, many of which have been driven by pressure from member states who were concerned about the organization''s declining effectiveness. The reforms that have attracted the most attention are those that restructured the governance framework under which decisions are made, replacing a system in which a small number of powerful members had disproportionate influence with one that gives greater voice to the broader membership. The reading notes that the reforms have also included changes to the criteria by which programs are evaluated, moving away from input measures — such as how much money was spent — toward outcome measures that assess whether the populations the programs are intended to serve have actually benefited. The reading concludes that while the reforms represent meaningful progress, their impact depends on whether the culture of the organization changes in ways that allow the new structures to function as intended, which is a challenge that structural reform alone cannot address.','hard'),
  (cid,77,254,'production','[TOEFL Speaking — 45s] The professor discusses the factors that determine whether a democracy functions well. Use relative clauses throughout.','',NULL,'The professor argues that democracies that function well share several characteristics, most of which relate to the quality of institutions rather than to formal constitutional arrangements. She identifies three factors that most strongly predict democratic performance. The first is the quality of the electoral system, which includes not just the rules by which votes are cast and counted, but the degree to which the process is insulated from the money, media influence, and administrative manipulation that can distort outcomes. The second is the independence of the judiciary, in whom citizens must be able to trust to resolve disputes in ways that are not predetermined by political pressure. The third is the quality of civil society — the organizations through which citizens mobilize, the media through which public debate occurs, and the educational institutions in which the capabilities for democratic participation are developed. The professor concludes that countries in which these three elements are strong can maintain democratic governance even when other conditions are challenging, while those in which all three are weak struggle to sustain democracy even when formal institutions appear intact.','hard'),
  (cid,77,255,'production','[TOEFL Speaking — 60s] Discuss what the reading and the professor say about an organization''s effectiveness. Use relative clauses throughout.','',NULL,'The reading and the professor both address what makes international organizations effective, but they emphasize different factors. The reading focuses on the formal institutional design of organizations — the rules by which decisions are made, the mandate on the basis of which they operate, and the mechanisms through which members can hold them accountable. It argues that organizations whose mandates are clear and whose governance structures are well-designed tend to perform better than those whose mandates are vague or whose governance is captured by a small number of powerful members. The professor largely agrees with this analysis but argues that the reading underestimates the importance of leadership and organizational culture, which she sees as factors that formal design cannot fully determine. She describes cases in which organizations whose formal design was sound had still performed poorly because the leaders who ran them prioritized institutional self-preservation over mission effectiveness, and cases in which organizations operating under quite challenging governance constraints had performed well because the leaders who headed them had built cultures in which performance was taken seriously. The professor concludes that the factors the reading identifies are necessary conditions for effectiveness — organizations whose governance is fundamentally broken cannot perform well regardless of leadership quality — but that they are not sufficient, and that attention to the human and cultural dimensions of organizational life is equally important.','hard'),
  (cid,77,256,'gap_fill','[TOEFL Speaking] The professor, _____ (expertise) _____ in _____ (the) _____ field _____ (span) _____ decades, argues _____ that _____ (the) _____ approaches _____ (most/likely/succeed) _____ (be) those _____ (take/passive) seriously _____ (the) _____ context _____ in _____ which _____ implementation _____ (occur) rather than _____ (those/assume) _____ universal _____ applicability.','whose / expertise / in / the / field / spans / decades / that / the / approaches / most likely to succeed / are those / that take seriously / the / context / in which / implementation / occurs / rather / those that assume / universal / applicability',NULL,'"Whose expertise spans" + "most likely to succeed" + "in which implementation occurs" for context-sensitive approach.','hard'),

  -- BLOCK 78: TOEFL Writing com relative clauses
  (cid,78,257,'production','[TOEFL Writing — 200 words] Write a paragraph on what makes a regulatory framework effective, using relative clauses throughout.','',NULL,'An effective regulatory framework is one that balances several objectives that are often in tension with each other. A framework that is well-designed achieves clarity — rules that all regulated parties can understand and apply — without sacrificing the flexibility that allows regulators to address circumstances whose specific character could not have been anticipated when the rules were written. It establishes enforcement mechanisms through which compliance can be verified and through which consequences for non-compliance can be imposed, in ways that are proportionate to the severity of the violation and that do not generate disproportionate compliance costs for actors whose scale makes the regulatory burden particularly heavy. A regulatory framework that works over time is one that includes processes through which it can be updated as the environment it regulates evolves, so that rules whose original purpose has been undermined by technological or market change can be revised before they generate perverse incentives. It also establishes accountability mechanisms for the regulator itself — processes by which the exercise of regulatory discretion can be challenged and by which patterns in regulatory decisions can be reviewed for consistency and rationality. Most fundamentally, an effective regulatory framework is one in which the logic that connects the rules to the objectives they are intended to serve is transparent — one in which both the regulated parties and the public can see why the rules are designed as they are and can evaluate whether they are achieving what they are supposed to achieve.','hard'),
  (cid,78,258,'production','[TOEFL Writing — 200 words] Write a body paragraph on the factors that determine whether international agreements are implemented, using relative clauses.','',NULL,'The factors that determine whether international agreements are actually implemented are quite different from the factors that determine whether they are initially negotiated and signed. Agreements that attract the most ambitious commitments at the negotiating table are not always those that produce the strongest results in practice, because the conditions under which commitments are made during negotiation are often very different from those under which they must be fulfilled during implementation. The countries for whom the commitments are most politically difficult to fulfill — those whose domestic constituencies are most resistant to the changes required — are often precisely those whose participation was most essential to securing the agreement and whose defection would most seriously undermine it. The mechanisms through which agreements are monitored and enforced are therefore critical: agreements that include robust monitoring requirements, transparent reporting systems through which compliance can be assessed, and consequences for non-compliance that are both credible and proportionate tend to produce significantly better implementation than those whose monitoring provisions are weak or whose enforcement mechanisms exist primarily on paper. Leadership also matters: the degree to which senior officials, whose attention and commitment shape what their institutions prioritize, treat the agreement as a genuine obligation rather than a rhetorical commitment strongly predicts whether the bureaucratic processes through which implementation occurs are adequately resourced and managed.','hard'),
  (cid,78,259,'gap_fill','[TOEFL Writing] _____ (the) _____ framework _____ (that) _____ (best/serve) _____ (the) _____ goals _____ (analysis/this) _____ (identify) _____ (be) one _____ (that) _____ (allow) _____ context-sensitive _____ (adaptation) _____ without _____ (sacrifice) _____ (the) _____ core _____ (principle) _____ (to/which) _____ (it) _____ (commit).','The / framework / that / best serves / the / goals / this analysis / identifies / is / one / that / allows / context-sensitive / adaptation / without / sacrificing / the / core / principles / to which / it / is committed',NULL,'"That best serves" + "that allows" + "to which it is committed" for framework evaluation.','hard'),
  (cid,78,260,'gap_fill','[TOEFL Writing] _____ (the) _____ evidence _____ (on/which) _____ (the) _____ recommendation _____ (base/passive) _____ (come) from _____ (study) _____ (whose) _____ methodological _____ rigor _____ (vary) — _____ (a) _____ limitation _____ (acknowledge/passive) in _____ (the) _____ literature but _____ (not/adequately/address/passive).','The / evidence / on which / the / recommendation / is based / comes / from / studies / whose / methodological / rigor / varies / a / limitation / acknowledged / in / the / literature / not adequately addressed',NULL,'"On which the recommendation is based" + "whose methodological rigor varies" for evidence quality caveat.','hard'),
  (cid,78,261,'gap_fill','[TOEFL Writing] _____ (the) _____ populations _____ (most/underserve/passive) by _____ (the) _____ current _____ system _____ (often/be) those _____ (for/whom) _____ (the) _____ system _____ (notionally/design/passive) — _____ (a) _____ paradox _____ (of/which) _____ (many) _____ are _____ (aware) but _____ (few) _____ (willing) to _____ (confront) _____ honestly.','The / populations / most underserved / by / the / current / system / are often those / for whom / the / system / was notionally designed / a / paradox / of which / many / are aware / few / are willing / confront / honestly',NULL,'"Most underserved by" + "for whom designed" + "of which many are aware" for systemic design failure.','hard'),
  (cid,78,262,'gap_fill','[TOEFL Writing] Ultimately, _____ (the) _____ test _____ by _____ which _____ (an) _____ institution _____ (should) _____ (judge/passive) _____ (be) not _____ (the) _____ quality of _____ (its) _____ (process) but _____ (the) _____ outcomes it _____ (produce) for _____ (the) _____ (population) it _____ (serve/passive) to _____ (notionally/serve).','Ultimately / the / test / by which / an / institution / should / be judged / is / not / the / quality / its / processes / the / outcomes / it / produces / for / the / populations / it / is notionally supposed / to / serve',NULL,'"By which it should be judged" + "it is notionally supposed to serve" for accountability criterion.','hard'),

  -- BLOCK 79: Relative clauses empilhadas (stacked)
  (cid,79,263,'gap_fill','_____ (the) _____ institutions _____ (that) _____ (produce) _____ (the) _____ most _____ lasting _____ (impact) _____ (not/always/be) those _____ (that) _____ (attract) _____ (the) _____ most _____ (attention) at _____ (the) _____ time of _____ (their) _____ creation — many of _____ (the) _____ arrangements _____ (that) _____ (govern) _____ (us) most _____ deeply _____ (be) ones _____ (that) _____ (develop) _____ (incrementally) and _____ (often) _____ (attract/passive) little _____ notice.','The / institutions / that / produce / the / most / lasting / impact / are not always those / that / attract / the / most / attention / at / the / time / their / creation / the / arrangements / that / govern / us / most deeply / are ones / that / developed / incrementally / were often attracted / little / notice',NULL,'Stacked defining RCs: "that produce/attract/govern/developed/attracted" for institutional development.','hard'),
  (cid,79,264,'gap_fill','What _____ (distinguish) _____ (the) _____ reforms _____ (that) _____ (survive) from those _____ (that) _____ (reverse/passive) _____ (be) _____ whether they _____ (create) _____ (constituencies) _____ (whose) _____ (interests) _____ (align) with _____ (their) _____ continuation — _____ (reform) _____ (that) _____ (do/not) this _____ (live) perpetually at _____ (the) _____ mercy of _____ (the) _____ next _____ election.','distinguishes / the / reforms / that / survive / those / that / are reversed / is / whether / they / create / constituencies / whose / interests / align / their / continuation / reforms / that / do not do / live / perpetually / the / mercy / the / next / election',NULL,'Stacked RCs "that survive/reversed/that create/whose interests align/that do not" for reform sustainability.','hard'),
  (cid,79,265,'gap_fill','This _____ (be) _____ precisely _____ (the) _____ kind of _____ (argument) _____ (that) _____ (gain) _____ (its) _____ (plausibility) from _____ evidence _____ (that) _____ (carefully/select/passive) and _____ (present/passive) _____ in _____ ways _____ (that) _____ (suppress) _____ (the) _____ complications _____ (that) _____ (emerge/would) if _____ (the) _____ full _____ evidence _____ (examine/passive).','This / is / precisely / the / kind / of / argument / that / gains / its / plausibility / from / evidence / that / is carefully selected / presented / in / ways / that / suppress / the / complications / that / would emerge / if / the / full / evidence / were examined',NULL,'Stacked RCs "that gains/carefully selected/that suppress/that would emerge" for evidence cherry-picking critique.','hard'),
  (cid,79,266,'gap_fill','_____ actors _____ (that) _____ (position) themselves at _____ (the) _____ center of _____ (network) _____ (through/which) _____ information _____ (flow) _____ (accrue) _____ (influence) that _____ (extend) far _____ beyond _____ (the) _____ formal _____ (authority) _____ (that) _____ (confer/passive) by _____ (their) _____ institutional _____ role.','The / actors / that / position / themselves / the / center / networks / through which / information / flows / accrue / influence / that / extends / far / beyond / the / formal / authority / that / is conferred / their / institutional / role',NULL,'Stacked RCs "that position/through which flows/that extends/that is conferred" for network power analysis.','hard'),
  (cid,79,267,'gap_fill','_____ (the) _____ explanations _____ (that) _____ (offer) the most _____ (satisfying) _____ (account) of _____ (the) _____ phenomenon _____ (often/be) not _____ (the) _____ ones _____ (that) _____ (best/support/passive) by _____ (the) _____ available _____ evidence — _____ (a) _____ gap _____ (that) _____ (create) _____ (the) _____ conditions _____ (in/which) _____ (confirmation) _____ (bias) _____ (flourish).','The / explanations / that / offer / the most / satisfying / account / the / phenomenon / are often not / the / ones / that / are best supported / the / available / evidence / a / gap / that / creates / the / conditions / in which / confirmation / bias / flourishes',NULL,'Stacked RCs "that offer/that are supported/that creates/in which flourishes" for confirmation bias analysis.','hard'),
  (cid,79,268,'multiple_choice','Which sentence MOST effectively uses stacked relative clauses?','The mechanism through which the intervention produces its effects — a process that involves the activation of social norms that are shared by the community members who participate — is not yet fully understood.','["The mechanism produces effects through social norms shared by community members who participate.","The mechanism through which the intervention produces its effects — a process that involves the activation of social norms that are shared by the community members who participate — is not yet fully understood.","The mechanism through which effects are produced involves social norms that community members share.","Through the mechanism, social norms that are shared by members who participate are activated."]','Three stacked RCs: "through which produces" + "that involves activation of norms" + "that are shared by members" + "who participate" = precise analytical sentence.','hard'),
  (cid,79,269,'gap_fill','The _____ (path) _____ (by/which) _____ (a) _____ policy _____ (arrive) at _____ (its) _____ current _____ form _____ (determine) much about _____ what _____ (possible/is) for _____ those _____ (who) _____ (seek) to _____ (modify) it — _____ (the) _____ (coalition) _____ (that) _____ (create) it and _____ (the) _____ (interest) _____ (that) _____ (sustain) it _____ (both/shape) _____ (the) _____ constraints _____ (within/which) _____ change _____ (occur).','The / path / by which / a / policy / arrived / at / its / current / form / determines / much / what / is possible / for / those / who / seek / modify / the / coalition / that / created / the / interests / that / sustain / both shape / the / constraints / within which / change / can occur',NULL,'Multi-stacked RCs "by which/who seek/that created/that sustain/within which" for path dependency.','hard'),
  (cid,79,270,'gap_fill','_____ (the) _____ question _____ (the) _____ analysis _____ (leave) _____ unanswered — _____ (the) _____ one _____ (that) _____ (resist) _____ (the) _____ most _____ obvious _____ _____ (resolution) and _____ (that) _____ (matter) _____ most _____ for _____ practice — _____ (be) _____ how to _____ (create) _____ (the) _____ conditions _____ (under/which) _____ (the) _____ knowledge _____ (already/produce/passive) _____ (can) _____ (translate/passive) into _____ action.','The / question / the / analysis / leaves / unanswered / the / one / that / resists / the / most / obvious / resolution / that / matters / most / practice / is / how / create / the / conditions / under which / the / knowledge / already produced / can / be translated / action',NULL,'Stacked RCs "that resists/that matters/under which/already produced" for knowledge-action gap conclusion.','hard'),

  -- BLOCK 80: Gap fill avançado com relative clauses
  (cid,80,271,'gap_fill','Nothing _____ (so/reliable/be) _____ an _____ indicator of _____ (the) _____ health of _____ (a) _____ democracy as _____ (the) _____ treatment of _____ (those) _____ (whose) _____ (view) _____ (challenge) _____ (the) _____ consensus — _____ (a) _____ system _____ (that) _____ (only/tolerate) _____ those _____ (who) _____ (agree) _____ (be) not _____ genuinely _____ (democratic/be).','is so reliable / an / indicator / the / health / a / democracy / as / the / treatment / those / whose / views / challenge / the / consensus / a / system / that / only tolerates / those / who / agree / is not / genuinely / democratic',NULL,'"Whose views challenge" + "that only tolerates/who agree" for democratic health indicator.','hard'),
  (cid,80,272,'gap_fill','_____ (the) _____ (innovation) _____ (that) _____ (ultimately/diffuse) widely _____ (not/always/be) those _____ (that) _____ (technically/superior/be) — _____ (they) _____ (often/be) those _____ (that) _____ (best/fit) _____ (the) _____ institutional, _____ cultural, and _____ economic _____ contexts _____ (in/which) _____ (they) _____ (adopt/passive).','The / innovations / that / ultimately diffuse / widely / are not always those / that / are technically superior / they / are often those / that / best fit / the / institutional / cultural / economic / contexts / in which / they / are adopted',NULL,'"That diffuse/that are superior/that best fit/in which adopted" for innovation diffusion analysis.','hard'),
  (cid,80,273,'gap_fill','_____ (the) _____ standards _____ (against/which) _____ (the) _____ performance _____ (evaluate/passive) _____ (matter) as _____ much as _____ (the) _____ performance _____ itself — choosing _____ (the) _____ wrong _____ benchmarks _____ (be) _____ (a) _____ reliable _____ way to _____ (obscure) _____ (the) _____ very _____ failures _____ (most/need/passive) _____ (address).','The / standards / against which / the / performance / is evaluated / matter / as / much / as / the / performance / itself / choosing / the / wrong / benchmarks / is / a / reliable / way / obscure / the / very / failures / most needed / address',NULL,'"Against which performance is evaluated" + "most needed to address" for benchmarking critique.','hard'),
  (cid,80,274,'gap_fill','_____ (the) _____ populations _____ (that) _____ (bear) _____ (the) _____ heaviest _____ (burden) of _____ (the) _____ transition _____ (often/be) those _____ (that) _____ (benefit) _____ least from _____ (the) _____ gains _____ (that) _____ (generate/passive) — _____ (an) _____ asymmetry _____ (that) _____ (undermines) _____ (the) _____ political _____ sustainability of _____ (the) _____ change _____ itself.','The / populations / that / bear / the / heaviest / burden / the / transition / are often those / that / benefit / least / the / gains / that / are generated / an / asymmetry / that / undermines / the / political / sustainability / the / change / itself',NULL,'"That bear/that benefit/that are generated/that undermines" for distributional asymmetry analysis.','hard'),
  (cid,80,275,'gap_fill','_____ (the) _____ debates _____ (that) _____ (most/consume) _____ public _____ attention _____ (often/be) not those _____ (that) _____ (most/consequential/be) — _____ (the) _____ questions _____ (on/which) _____ (most) _____ is _____ actually _____ at _____ stake _____ (often/receive/passive) _____ less _____ coverage than _____ (the) _____ controversies _____ (generate) _____ (the) _____ most _____ heat.','The / debates / that / most consume / public / attention / are often not those / that / are most consequential / the / questions / on which / most / actually / at / stake / are often received / less / coverage / than / the / controversies / that / generate / the / most / heat',NULL,'"That most consume/consequential/on which most/generate most heat" for media coverage critique.','hard'),
  (cid,80,276,'multiple_choice','Which complex relative clause construction MOST effectively builds an analytical argument?','The institutional arrangements that proved most resilient were those that had been designed with redundancy — systems in which multiple actors shared responsibility for outcomes that mattered, so that the failure of any one could be compensated by others.','["The institutional arrangements proved most resilient when designed with redundancy.","The institutional arrangements that proved most resilient were those that had been designed with redundancy — systems in which multiple actors shared responsibility for outcomes that mattered, so that the failure of any one could be compensated by others.","Institutions designed with redundancy are more resilient than others.","Resilient institutions were those designed with redundancy in which actors shared responsibility."]','Four RCs: "that proved" + "that had been designed" + "in which shared" + "that mattered" = richest analytical specification.','hard'),
  (cid,80,277,'gap_fill','_____ (the) _____ choices _____ (by/which) _____ (we) _____ define _____ (the) _____ problem _____ (determine) _____ (the) _____ range of _____ (solution) _____ (that) _____ (it) _____ (possible/be) to _____ (propose) — _____ (a) _____ (process) _____ (in/which) _____ (apparently) _____ technical _____ decisions _____ (have) _____ deeply _____ political _____ (consequence) _____ (that) _____ (often) _____ (invisible/remain).','The / choices / by which / we / define / the / problem / determine / the / range / solutions / that / it / is possible / propose / a / process / in which / apparently / technical / decisions / have / deeply / political / consequences / that / often / remain / invisible',NULL,'"By which we define" + "that it is possible" + "in which decisions" + "that remain invisible" for agenda-setting analysis.','hard'),
  (cid,80,278,'gap_fill','_____ (the) _____ question _____ (of/which) _____ intervention _____ (most/likely/be) to _____ (succeed) _____ in _____ _____ (a) _____ given _____ context _____ (one) _____ that _____ (cannot) _____ answer _____ in _____ (the) _____ abstract — it _____ (require) _____ attention to _____ (the) _____ specific _____ features of _____ (the) _____ context _____ (that) _____ (most/determine) _____ (the) _____ conditions _____ (under/which) _____ implementation _____ (occur).','The / question / of which / intervention / is most likely / to / succeed / in / a / given / context / is one / that / cannot / be answered / in / the / abstract / it / requires / attention / the / specific / features / the / context / that / most determine / the / conditions / under which / implementation / occurs',NULL,'"Of which intervention" + "that cannot be answered" + "that most determine" + "under which occurs" for context-sensitivity conclusion.','hard'),

  -- BLOCK 81: Produção avançada
  (cid,81,279,'production','[TOEFL Writing — 200 words] Write a paragraph on what makes evidence compelling, using relative clauses throughout.','',NULL,'Evidence that genuinely compels revision of existing views is harder to produce than the volume of academic publication might suggest. The studies that actually change minds — as opposed to those that merely add to a growing pile of work that confirms what researchers already believed — tend to share several characteristics. They address questions that are genuinely contested, rather than those whose answers are already widely agreed upon. They use methods by which the specific causal claims being made can be credibly tested, rather than methods whose results admit multiple plausible interpretations. They are designed in ways that rule out the most plausible alternative explanations for the observed outcomes, so that the explanation on which the study''s conclusions rest is the one that the evidence actually supports. And they are reported with a transparency that makes it possible for other researchers, whose independent judgment is the ultimate test of any scientific claim, to assess the validity of the methods and the appropriateness of the conclusions. Evidence that meets these criteria is genuinely valuable, and the fields in which it has accumulated most systematically are those that have made the most durable contributions to both knowledge and practice. The challenge for any field is to create the institutional conditions that reward the production of this kind of evidence rather than rewarding the production of evidence that is simply easier to generate.','hard'),
  (cid,81,280,'production','[TOEFL Writing — 200 words] Write a body paragraph on the characteristics of institutions that maintain their legitimacy over time, using relative clauses.','',NULL,'Institutions that maintain their legitimacy over extended periods — decades and sometimes generations — tend to share characteristics that distinguish them from those whose authority is more fragile. The most important is consistency: institutions that apply their rules and procedures consistently, regardless of who is affected, build a track record of impartiality that becomes a form of institutional capital on which they can draw when their decisions are contested. Institutions whose decisions are perceived to favor the powerful over the weak, or in-groups over out-groups, systematically deplete this capital, often without recognizing that they are doing so until the depletion has advanced to a point that is difficult to reverse. A second characteristic is adaptability: institutions that have built-in mechanisms through which they can revise their rules and procedures in response to changing circumstances maintain relevance over time, while those whose structures are too rigid to accommodate change become increasingly disconnected from the realities to which they are supposed to respond. A third is transparency: institutions whose reasoning is legible to those they govern — whose decisions come with explanations that make the logic visible — generate more durable consent than those whose authority rests on the claim to specialized knowledge that cannot be shared. Institutions that combine all three characteristics are rare; those that sustain them over time are rarer still.','hard'),
  (cid,81,281,'gap_fill','[TOEFL Writing] What _____ (matter) _____ most _____ (not/be) _____ (whether) _____ (the) _____ approach _____ (elegant/is) but _____ whether it _____ (produce) _____ (the) _____ results _____ (that) _____ those _____ (who) _____ (bear) _____ (the) _____ costs _____ (were/promise/passive) — _____ (the) _____ populations _____ (for/whom) _____ (the) _____ intervention _____ (design/passive) _____ (best/the/judge) of this.','matters / most / is not / whether / the / approach / is elegant / whether / produces / the / results / that / those / who / bear / the / costs / were promised / the / populations / for whom / the / intervention / was designed / are the best judges / of',NULL,'"That those who bear/were promised" + "for whom the intervention was designed" for accountability to beneficiaries.','hard'),
  (cid,81,282,'gap_fill','[TOEFL Writing] In _____ (the) _____ end, _____ (the) _____ institutions _____ (that) _____ (matter) _____ most _____ (not/be) those _____ (that) _____ (build/passive) most _____ impressively but _____ those _____ (that) _____ (deliver) most _____ consistently — _____ (the) _____ ones _____ (through/which) _____ (the) _____ ordinary _____ people _____ (who/depend) on _____ (them) _____ (actually/receive) _____ (the) _____ (service) they _____ need.','the / end / the / institutions / that / matter / most / are not those / that / are built / most / impressively / those / that / deliver / most / consistently / the / ones / through which / the / ordinary / people / who depend / on / them / actually receive / the / services / they / need',NULL,'Stacked RCs "that matter/built/that deliver/through which/who depend" for institutional accountability conclusion.','hard'),
  (cid,81,283,'gap_fill','[TOEFL Writing] The _____ (tension) _____ between _____ what _____ (know/passive) and what _____ (do/passive) _____ (be) not _____ (a) _____ failure of _____ (knowledge) — it _____ (be) _____ (a) _____ failure of _____ (the) _____ (political) and _____ institutional _____ (condition) _____ (under/which) _____ knowledge _____ (can) _____ (translate/passive) into _____ action.','The / tension / between / what / is known / what / is done / is not / a / failure / knowledge / it / is / a / failure / the / political / institutional / conditions / under which / knowledge / can / be translated / action',NULL,'"Under which knowledge can be translated into action" for knowledge-action gap argument.','medium'),
  (cid,81,284,'gap_fill','[TOEFL Writing] _____ (the) _____ scholars _____ (whose) _____ work _____ (most/endure) _____ (tend/be) _____ those _____ (who) _____ (ask) _____ (the) _____ right _____ questions rather than _____ (those) _____ (who) _____ (provide) _____ (the) _____ most _____ technically _____ sophisticated _____ answers to _____ (question) _____ (that) _____ _____ (not/matter/ultimately).','The / scholars / whose / work / most endures / tend to be / those / who / ask / the / right / questions / rather / those / who / provide / the / most / technically / sophisticated / answers / to / questions / that / ultimately do not matter',NULL,'"Whose work most endures" + "who ask/who provide/that do not matter" for scholarly significance argument.','hard'),
  (cid,81,285,'gap_fill','[TOEFL Writing] _____ (the) _____ arguments _____ (that) _____ (prove) most _____ (durable) _____ (not/those/be) _____ that _____ are _____ most _____ _____ (forcefully/assert) but _____ (those) _____ (most/carefully/ground) in _____ evidence _____ (that) _____ (survive) _____ scrutiny _____ and _____ (most/transparently/connect) _____ (the) _____ claims _____ (to/which) _____ they _____ (commit).','The / arguments / that / prove / most / durable / are not those / that / most forcefully asserted / those / most carefully grounded / in / evidence / that / survives / scrutiny / most transparently connected / to / the / claims / to which / they / commit',NULL,'"That prove/forcefully asserted/carefully grounded/that survives/to which commit" for argument quality.','hard'),
  (cid,81,286,'gap_fill','[TOEFL Writing] The discipline _____ (has) _____ matured _____ to _____ (the) _____ point _____ where _____ _____ (it/capable/is) of _____ (generating) _____ the _____ kind _____ of _____ evidence _____ (on/which) _____ _____ (confident) _____ policy _____ recommendations _____ can _____ _____ (base/passive) — _____ (a) _____ development _____ (that) _____ _____ (few) _____ (predict/would) _____ two _____ decades _____ ago.','has / matured / to / the / point / where / it / is capable / generating / the / kind / of / evidence / on which / confident / policy / recommendations / can / be based / a / development / that / few / predicted / two / decades / ago',NULL,'"Where it is capable" + "on which recommendations can be based" + "that few predicted" for disciplinary maturity.','hard'),

  -- BLOCK 82: Exercícios finais
  (cid,82,287,'production','[TOEFL Speaking — 45s] Summarize what the reading says about institutions that have maintained their effectiveness over time. Use relative clauses throughout.','',NULL,'The reading identifies several characteristics that institutions which have maintained their effectiveness over extended periods tend to share. First, these institutions have clear mandates that define what they are supposed to achieve and against which their performance can be measured — unlike institutions whose mandates are vague, they can be held accountable in ways that create genuine incentives for performance. Second, they have governance structures through which decisions are made transparently and in which the reasoning behind decisions is available to those affected by them. Third, they have developed cultures in which performance is genuinely valued and in which individuals whose work falls short of standards face real consequences, rather than cultures in which institutional solidarity protects poor performers from accountability. Fourth, they have mechanisms by which they learn from experience — processes that generate feedback about what is working and what is not, and through which that feedback is actually used to improve practice. The reading concludes that institutions that possess all four of these characteristics are unusual, and that most institutions that have maintained effectiveness over time have done so by compensating for weaknesses in some areas with particular strengths in others.','hard'),
  (cid,82,288,'production','[TOEFL Speaking — 60s] The reading and professor discuss what factors determine whether an approach is adopted. Compare using relative clauses.','',NULL,'The reading and the professor address the same question — what determines whether a new approach is adopted — but they reach different conclusions that reflect different understandings of how institutional change works. The reading focuses on the quality of the evidence by which the approach is supported, arguing that approaches whose effectiveness is well-documented tend to be adopted more readily than those for whom the evidence base is weaker. It also points to the champions of innovation — the individuals who advocate for new approaches — as key factors, arguing that approaches which are promoted by respected figures who have access to decision-makers are more likely to receive serious consideration. The professor largely accepts these points but argues that they account for only part of the story. She emphasizes the role of institutional politics — the interests of those whose position depends on maintaining existing arrangements, the rules through which change must be approved, and the timing relative to political cycles that creates windows of opportunity in which change is possible. She gives examples of approaches whose evidence base was strong and whose champions were influential, but which were still blocked for years by actors whose interests were threatened by the change, and of approaches whose evidence base was weak but which were adopted because they aligned with the political priorities of those who held decision-making authority. The professor concludes that understanding adoption requires attending to both the evidence-based factors the reading emphasizes and the political and institutional factors it underemphasizes.','hard'),
  (cid,82,289,'gap_fill','[TOEFL Writing] The question _____ (answer/passive/not/yet) _____ is _____ not whether _____ (the) _____ approach _____ (work) _____ in _____ (the) _____ conditions _____ (under/which) _____ it _____ (test/passive) but _____ whether _____ it _____ (generalise) _____ to _____ (the) _____ range of _____ contexts _____ in _____ (which) _____ policymakers _____ (seek) to _____ (apply) it.','has not yet been answered / is / whether / the / approach / works / in / the / conditions / under which / it / was tested / whether / it / will generalise / to / the / range / contexts / in / which / policymakers / seek / apply',NULL,'"Under which it was tested" + "in which policymakers seek" for generalizability question.','medium'),
  (cid,82,290,'gap_fill','[TOEFL Writing] The most _____ important _____ (test) _____ (of/any/analysis) is whether _____ (the) _____ conclusions _____ (to/which) _____ it _____ (lead) _____ (withstand) _____ scrutiny from _____ (those) _____ (who) _____ (approach) _____ (the) _____ evidence _____ without _____ (the) _____ assumptions _____ (on/which) _____ (the) _____ original _____ analysis _____ (rest).','most / important / test / of any analysis / is / whether / the / conclusions / to which / it / leads / withstand / scrutiny / those / who / approach / the / evidence / without / the / assumptions / on which / the / original / analysis / rests',NULL,'"To which it leads" + "who approach" + "on which the analysis rests" for epistemic test of analysis.','hard'),
  (cid,82,291,'gap_fill','[TOEFL Writing] What _____ (need/passive) is _____ not _____ more _____ _____ (evidence) _____ (point) in _____ (the) _____ same _____ direction but _____ (a) _____ better _____ _____ (understanding) of _____ (the) _____ conditions _____ (under/which) _____ (the) _____ existing _____ evidence _____ (can) _____ (translate/passive) _____ into _____ (the) _____ changes in _____ practice _____ (that) _____ it _____ (implies).','is needed / is not / more / evidence / pointing / the / same / direction / a / better / understanding / the / conditions / under which / the / existing / evidence / can / be translated / into / the / changes / practice / that / it / implies',NULL,'"Under which evidence can be translated" + "that it implies" for evidence-to-practice conclusion.','hard'),
  (cid,82,292,'gap_fill','[TOEFL Writing] The legacy _____ (that) _____ _____ (generation/a) _____ (leave) is _____ (judg/passive) not _____ by _____ (the) _____ _____ (intentions) _____ (it) _____ (articulate) but by _____ (the) _____ _____ (conditions) _____ (under/which) _____ (those) _____ (who) _____ (follow) _____ (must) _____ (operate) — _____ (the) _____ most _____ honest _____ (gift) _____ (generation/a) _____ (give) _____ (its) _____ (successor) is _____ the _____ _____ (one) _____ (that) _____ (leave) _____ them _____ (better-off).','that / a / generation / leaves / is judged / not / the / intentions / it / articulates / the / conditions / under which / those / who / follow / must / operate / the / most / honest / gift / a / generation / can give / its / successors / is / the / one / that / leaves / them / better-off',NULL,'"That a generation leaves/that it articulates/under which those follow/that leaves them" for generational legacy conclusion.','hard'),
  (cid,82,293,'gap_fill','In _____ (the) _____ final _____ analysis, _____ (the) _____ structures _____ (that) _____ (govern) _____ (us), _____ (the) _____ ideas _____ (by/which) _____ (we) _____ (make) _____ sense _____ of _____ (the) _____ world, and _____ (the) _____ institutions _____ (through/which) _____ (we) _____ (make) _____ collective _____ decisions _____ (all/be) _____ (human) _____ (creation) _____ (that) _____ (we) _____ can _____ (change) — _____ a _____ (recognition) _____ (that) _____ (should) _____ (be) _____ both _____ (humbling) _____ and _____ (empowering).','In / the / final / analysis / the / structures / that / govern / us / the / ideas / by which / we / make / sense / of / the / world / the / institutions / through which / we / make / collective / decisions / are all / human / creations / that / we / can / change / a / recognition / that / should / be / both / humbling / and / empowering',NULL,'"That govern/by which we make/through which we make/that we can change/that should be" for human agency conclusion.','hard'),
  (cid,82,294,'production','[TOEFL Writing — Final 200 words] Write a conclusion on what shapes the questions that scholars ask and the answers they find, using relative clauses throughout.','',NULL,'The questions that scholars ask and the answers they find are shaped by factors that operate at multiple levels simultaneously. At the level of individual researchers, the questions that are pursued reflect the intellectual concerns, methodological training, and institutional contexts that shape what seems interesting, tractable, and publishable. Researchers whose training emphasized certain methods will tend to ask the questions those methods are designed to answer, potentially missing questions that require different approaches. At the level of the discipline, the consensus frameworks through which scholarly conversations are organized determine what counts as a contribution — ideas that challenge foundational assumptions face higher barriers than those that extend existing frameworks, and questions for which existing methods provide no clear answer tend to be marginalized regardless of their importance. At the level of society, the problems whose urgency commands funding and attention shape the questions that researchers have resources to pursue, creating systematic tendencies in what gets studied and what does not. None of these influences is determinative — scholars who recognize the structures that shape their work can compensate for them, and the history of science includes many instances in which important questions were identified and pursued despite institutional resistance. But the recognition that the questions we ask are themselves answers to prior questions about what matters and what is knowable is itself an important contribution to the reflexive understanding that good scholarship requires.','hard'),
  (cid,82,295,'gap_fill','The world _____ (that) _____ _____ (we) _____ (inhabit) is _____ (not) _____ (the) _____ world _____ (as) _____ (it) _____ (is) but _____ (the) _____ world _____ (as) _____ (we) _____ (understand) _____ it — and _____ (the) _____ concepts _____ (through/which) _____ (we) _____ (understand) _____ it _____ (shape) what _____ (we) _____ (see), what _____ (we) _____ (miss), and _____ (the) _____ solutions _____ (we) _____ (capable/are) of _____ (imagin).','The / world / that / we / inhabit / is / not / the / world / as / it / is / the / world / as / we / understand / it / the / concepts / through which / we / understand / it / shape / what / we / see / what / we / miss / the / solutions / we / are capable / imagining',NULL,'"That we inhabit/through which we understand/we are capable of imagining" for epistemic conclusion.','hard'},
  (cid,82,296,'gap_fill','The _____ (institutions) _____ (that) _____ (shape) _____ (the) _____ most _____ consequential _____ (outcome) _____ (tend/be) those _____ (whose) _____ workings _____ (least/visible) to _____ those _____ (whose) _____ lives _____ (most/affect/passive) by _____ (them) — _____ (a) _____ fact _____ (that) _____ (has/important) _____ (implication) for _____ (the) _____ design of _____ (accountability) _____ mechanisms.','The / institutions / that / shape / the / most / consequential / outcomes / tend to be those / whose / workings / are least visible / to / those / whose / lives / are most affected / by / them / a / fact / that / has important / implications / for / the / design / accountability / mechanisms',NULL,'"That shape/whose workings/whose lives/that has implications" for institutional visibility argument.','hard'},
  (cid,82,297,'production','[TOEFL Writing — 200 words] Write a conclusion on what institutions that endure over time have in common, using relative clauses throughout.','',NULL,'The institutions that endure over time — those that maintain their relevance, their legitimacy, and their effectiveness across changing circumstances — share characteristics that reward analysis. They possess clear purposes to which their activities are connected and against which their performance can be assessed; institutions whose purposes have become unclear, or that have accumulated activities whose connection to their original mandate is tenuous, tend to be less resilient when circumstances change. They have governance structures through which authority is exercised in ways that are broadly legitimate — structures that distribute power sufficiently that no single actor whose interests diverge from the institution''s purpose can capture it entirely. They have cultures in which the mission is taken seriously — in which the individuals who make up the institution understand what they are supposed to be doing and why, and in which the informal norms that govern behavior reinforce rather than undermine the formal rules through which the institution operates. And they have mechanisms by which they learn — processes that generate feedback about what is working, through which that feedback reaches decision-makers, and by which it is actually used to improve practice. Institutions that possess all four of these characteristics are genuinely rare; those that have maintained them over extended periods are rarer still. But they exist, and the fact that they do demonstrates that institutional excellence is achievable — and provides models whose lessons can be learned and applied.','hard'},
  (cid,82,298,'gap_fill','Whatever _____ _____ (approach) _____ (adopt/passive), _____ (the) _____ goal _____ (remain) _____ consistent: to _____ (understand) _____ (the) _____ world in _____ ways _____ (that) _____ (allow) _____ (us) to _____ (act) _____ on _____ it _____ more _____ _____ (wisely) — _____ (a) _____ purpose _____ (that) _____ (justify) _____ (the) _____ sustained _____ investment of _____ effort _____ (that) _____ serious _____ scholarship _____ (require).','Whatever / approach / is adopted / the / goal / remains / consistent / understand / the / world / in / ways / that / allow / us / act / on / it / more / wisely / a / purpose / that / justifies / the / sustained / investment / effort / that / serious / scholarship / requires',NULL,'"That allow us to act" + "that justifies/that requires" for scholarship purpose conclusion.','medium'),
  (cid,82,299,'gap_fill','We _____ _____ (inhabit) _____ (the) _____ institutions _____ (that) _____ (shape) _____ (us) and _____ (shape) _____ (the) _____ institutions _____ (in/which) _____ (we) _____ _____ (live) — _____ (the) _____ relationship _____ (that) _____ (best/characterize) as _____ _____ (recursive) rather than _____ _____ (simply/directional).','We / inhabit / the / institutions / that / shape / us / shape / the / institutions / in which / we / live / the / relationship / that / is best characterized / as / recursive / rather / than / simply directional',NULL,'"That shape us/in which we live/that is best characterized" for recursive human-institution relationship.','medium'),
  (cid,82,300,'production','[TOEFL Writing — Final capstone 200 words] Write a conclusion on what the study of governance reveals about human capacity for collective action, using relative clauses throughout.','',NULL,'The study of governance — of the institutions through which collective decisions are made and through which collective resources are mobilized — reveals something both humbling and hopeful about the human capacity for cooperation. It is humbling because the evidence about the conditions under which institutions actually deliver on their promises is sobering: the gap between institutions as they appear on paper and institutions as they function in practice is often wide, the interests that distort institutional behavior are persistent, and the reforms that seem most promising are often captured or diluted by the very interests they are designed to constrain. But it is hopeful because the historical record includes many cases in which collective action problems that seemed intractable were solved, in which institutions that seemed irredeemably broken were reformed, and in which the patterns of behavior that seemed most deeply embedded were changed by actors whose persistence and ingenuity created possibilities that more cautious observers had dismissed. The lesson that this record teaches is not that good governance is easy — the conditions under which it has been achieved make clear that it is not — but that it is possible, and that the gap between what governance delivers and what it is capable of delivering is not a fixed feature of the human condition but a reflection of choices that have been made and that can be made differently. That is the most important thing the study of institutions has to teach, and the reason why the questions to which it is devoted will remain worth asking.','hard')

